h,w=30,8
markers={(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)}
out=[[8]*w for _ in range(h)]
for r,c in markers: out[r][c]=7
for r in range(h):
 cs=[c for rr,c in markers if rr==r]
 if len(cs)>1:
  for c in range(min(cs),max(cs)+1):
   if (r,c) not in markers: out[r][c]=3
for c in range(w):
 rs=[r for r,cc in markers if cc==c]
 if len(rs)>1:
  for r in range(min(rs),max(rs)+1):
   if (r,c) not in markers: out[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in out))
